    "Držite proizvod podalje od djece i osoba kojima nije namijenjen.",
    "Nemojte koristiti oštećene, istekle ili nepravilno pohranjene tablete.",
    "Izbjegavajte alkohol ili teške, masne obroke u vrijeme kada želite da vaše tijelo najbolje funkcioniše.",
